\label{def:concave-closure}
    The \emph{concave closure} $f^+:[0,1]^{\mathcal{U}}\to \mathbb{R}$ of a set function $f:2^{\mathcal{U}}\to \mathbb{R}$ maps each vector $\mathbf{x}\in [0,1]^{\mathcal{U}}$ to
    $$f^+(\mathbf{x})\triangleq \max\left\{\sum_{S\subseteq \mathcal{U}} \alpha_S \cdot f(S) \;\middle\vert\; \sum_{S\subseteq \mathcal{U}} \alpha_S = 1,\; \mathbf{\alpha}\geq \mathbf{0},\;\sum_{S\ni e} \alpha_S = x_e \;\forall e\in \mathcal{U} \right\}.$$

\label{def:coverage}
A function $f: 2^{\mathcal{U}} \to \mathbb{R}$ is a \emph{coverage function} if there exists another universe $\mathcal{U}'$ with non-negative weights $w(u)\geq 0$ for each $u \in \mathcal{U}'$ and subsets $A_e$ of $\mathcal{U}'$ for each $e\in \mathcal{U}$ such that $f(S) = \sum_{e\in \bigcup_{i\in S} A_i} w(e)$. 
If $w(e) = c$ for all $e$, then $f$ is an \emph{unweighted} coverage function.

\label{subadditivity}
    Let $f:2^{\mathcal{U}}\to \mathbb{R}_+$ be submodular, $\mathbf{x}\in [0,1]^{\mathcal{U}}$ be a vector and let $A,B$ partition $\mathcal{U}$. Then, 
    $$f^+(\mathbf{x})\leq f^+(\mathbf{x}_{\mid A}) + f^+(\mathbf{x}_{\mid B}).$$

Draw a random set $R\subseteq \mathcal{U}$ from the expectation-maximizing distribution with marginals $\mathbf{x}$. Then, by submodularity and hence sub-additivity of $f$, and the definition of $f^+(\mathbf{x}_{\mid C})$, we get that 
    \begin{align*}
    f^+(\mathbf{x}) & = \mathbb{E}[f(R)] \leq \mathbb{E}[f(R\cap A)+f(R\cap B)] \leq f^+(\mathbf{x}_{\mid A}) + f^+(\mathbf{x}_{\mid B}). \qedhere 
    \end{align*}

Let $S\subseteq \mathcal{U}$ be a random set with marginals $\Pr[e\in S]=x_e$ maximizing $\mathbb{E}[f_i(S)]$. So, $f_i^+(\mathbf{x})=\mathbb{E}[f_i(S)]$. For all parts $P\in \mathcal{P}_i$, since $|\{e\in P \mid x_e>0\}|\leq 1$, for any realization of $S$ we have that $|S\cap P|\leq 1$, and by  \Cref{cor:closed-form}, $f_i(S)=g(|S\cap \mathcal{U}_i|)\triangleq 1-(1-1/k)^{|S\cap \mathcal{U}_i|}$.~So, by Jensen's inequality and since $\mathbb{E}[|S\cap \mathcal{U}_i|]\leq \|\mathbf{x}\|_1$ by linearity of expectation, we get the desired inequality:
    \begin{align*}
        f_i^+(\mathbf{x}) & =\mathbb{E}[f_i(S)] = \mathbb{E}[g(|S\cap \mathcal{U}_i|)] \leq g(\mathbb{E}[|S\cap \mathcal{U}_i|]) \leq g(\|\mathbf{x}\|_1) = 1-(1-1/k)^{\|\mathbf{x}\|_1}. \qedhere
    \end{align*}

\label{fact:parameters}
    There exist $k=k(n)$ and $u=u(n)$ satisfying:
    \begin{enumerate}
        \item $k=\omega(1)$,
        and
        \item \label{ineq:u>>npoly(k)} $u=\omega(nk^2)$, and
        \item \label{ineq:k<<u^(1-1/k)} $k=o(u^{1-1/k})$, and
        \item \label{ineq:bday-threshold} $n=\omega(u^{1-1/k}(k\ln n)^{1/k})$.
    \end{enumerate}

\label{lem:online-iid-allocation-decomposition}
    For this i.i.d.~OSW instance, any fractional online algorithm's output $\mathbf{x}\in [0,1]^{[n]\times \mathcal{U}}$ decomposes into $\mathbf{x}=(\mathbf{x}-\mathbf{z})+\mathbf{z}$ satisfying $\mathbf{0}\leq \mathbf{z}\leq \mathbf{x}$ and
    \begin{enumerate}
        \item \label{prop:z-small} $\mathbb{E}[\|\mathbf{z}\|_1]=o(nk)$.
        \item \label{prop:no-repeates} $|\{e\in P \mid (x-z)_{i,e} >0\}|\leq 1$ for all buyers $i$ and parts $P\in \mathcal{P}_i$.
    \end{enumerate}

\label{lem:online-iid-allocation-structure}
   For any possibly random fractional allocation $\mathbf{x}\in [0,1]^{[n]\times \mathcal{U}}$ with $\|\mathbf{x}\|_1\leq nk$ decomposable into $\mathbf{x}=(\mathbf{x}-\mathbf{z})+\mathbf{z}$ as in \Cref{lem:online-iid-allocation-decomposition}, 
   $$\mathbb{E}\left[\sum_if_i^+(\mathbf{x}^{(i)})\right]\leq \mathbb{E}\left[\sum_i\left(1-\left(1-\frac{1}{k}\right)^{\|\mathbf{x}^{(i)} \|_1}\right)\right] + o(n).$$

Let $C$ be the number of ``collisions'', i.e., pairs of time steps with arrivals of the same type. Then $D\geq nk-C$. (This inequality is strict if any item type arrives three or more times.) 
        Now, each of the $\binom{m}{2}\leq m^2 = n^2k^2$ pairs of arrival times has a probability $1/u$ of colliding. Therefore, by linearity of expectation, and since $nk=o(u)$ by \Cref{fact:parameters}, we have that indeed
        \begin{align*}
            \mathbb{E}[D] & \geq nk-\mathbb{E}[C] \geq nk-n^2k^2/u = nk-o(nk).\qedhere 
        \end{align*}

Associate $\mathcal{P}_i$, buyer $i$'s random partition of $\mathcal{U}$, with a random permutation of the $u$ items, $\pi\in S_u$, and a partition into $u/k$ parts, where the $r^{th}$ part is 
    $$P_r \triangleq \{\pi((r-1)k+1),\; \pi((r-1)k+2),\dots,\; \pi(rk)\}.$$
    For any part $P_r$, let $I_r=\mathds{1}[P_r\subseteq S]$ be the indicator that $P_r$ is contained in $S$. Then, for~all~$r$,
    $$Pr[I_r=1]=q\triangleq \frac{\binom{s}{k}}{\binom{u}{k}}.$$
    Let $Y_j\triangleq \mathds{1}[\pi(j)\in S]$ be an indicator for $\pi(j)$ belonging to the set $S$. The random vector $\mathbf{Y}\in \{0,1\}^\mathcal{U}$ is drawn from a permutation distribution (over a vector with $s$ ones and $u-s$ zeros), and so the $(Y_j)_j$ variables are negatively associated (NA) \cite{joag1983negative}. 
    But since the indicator variables $I_r \triangleq \bigwedge_{j\in ((r-1)k,rk]} Y_j$ are increasing functions of disjoint NA variables, the $I_r$ are also NA, and hence negative cylinder dependent (NCD) \cite{joag1983negative}, and in particular $ \Pr\left[\bigwedge_{r=1}^{u/k} (I_r=0)\right] \leq \prod_{r=1}^{u/k}  \Pr\left[I_r=0\right] $. Therefore,
    \begin{align*}
    \Pr[\forall P\in \mathcal{P}_i: P\not \subseteq S] & = 
    \Pr\left[\bigwedge_{r=1}^{u/k} (I_r=0)\right] \\ & \leq \left(1-q\right)^{u/k} 
    & \textrm{NA $\Rightarrow$ NCD} \\ 
    & \leq \exp\left(-q\cdot \frac{u}{k}\right) & 1-z\leq \exp(-z) \\
    & \leq \exp\left(-\left(\frac{s}{2u}\right)^k\cdot \frac{u}{k}\right) &\textrm{See proof below}\\
    & =\exp(-s^k / (2^ku^{k-1}k)) \\
    & \leq n^{-10},  & s\geq 2u^{1-1/k}(10k\ln n)^{1/k}
    \end{align*}
    where the second-to-last inequality (labeled ``see proof below'') used that, for $s\geq 2k$,
    \begin{align*}
    q=\frac{\binom{s}{k}}{\binom{u}{k}} &= \prod_{j=0}^{k-1} \frac{s-j}{u-j}\geq \prod_{j=0}^{k-1} \frac{s-j}{u} \geq \prod_{j=0}^{k-1} \frac{s/2}{u} = \left(\frac{s}{2u}\right)^k.\qedhere
    \end{align*}

\label{lem:offline-adv-allocation}
For the adversarial-order OSW instance created by \Cref{alg:adversarial-OSW}, 
$$OPT(SW)\geq n(1-o(1)).$$

\label{lem:online-adv-structure}
    On the adversarial-order OSW instance created by \Cref{alg:adversarial-OSW}, any fractional OSW algorithm $ALG$ has output $\mathbf{x}$
   decomposable into $\mathbf{x}=(\mathbf{x}-\mathbf{z})+\mathbf{z}$ as in \Cref{lem:online-iid-allocation-decomposition}.

\label{lem:online-adv-allocation}
    On the adversarial-order OSW instance created by \Cref{alg:adversarial-OSW}, any (randomized or fractional) OSW algorithm $ALG$ has 
    $$ALG(SW)\leq n(\nicefrac{1}{2}+\nicefrac{1}{(2c)}+o(1)).$$

\label{fact:g+upper-bound}
	For any arrival sequence $\sigma\in \mathcal{U}^m$ and fractional allocation vector $\mathbf{x}\in \mathrm{conv}(\mathcal{M}_\sigma)$,
	\[ g^+_{\sigma}(\mathbf{x}) \leq \sum_{i=1}^n f^+_i(\mathbf{x}^{(i)}). \]

\label{obs1}
	For the i.i.d.\ instance constructed in \Cref{sec:hardness} and the uniform fractional assignment $\mathbf{x}^*$, we have:
	\begin{enumerate}
		\item $\mathbb{E}[g^+_\sigma(\mathbf{x}^*)] \le \left(1 - \frac{1}{e}\right)n + o(n)$,
		\item $\mathbb{E}[g^1(\mathbf{x}^*)] \ge n - o(n)$,
		\item $\mathbb{E}[g^2(\mathbf{x}^*)] \ge n - o(n)$.
	\end{enumerate}

\label{thm:noniidOSW}
     OSW under non-i.i.d.~arrivals admits:
     \begin{enumerate}
         \item a $(1-\nicefrac{1}{e})$-competitive algorithm, and
         \item a $(1-\nicefrac{1}{e}-o(1))$-competitive algorithm with running time $\mathrm{poly}(n,m,u)$.
     \end{enumerate}

\label{lem:correlation-submod}
        Let $f:2^E\to\mathbb{R}_+$ be a monotone submodular function and $\mathbf{x}\in [0,1]^E$. Then,
        $$F(\mathbf{x})\geq (1-1/e)\cdot f^+(\mathbf{x}).$$

Consider a run of the above algorithm $ALG$ on a vector $\mathbf{y}\in \mathcal{P}$, for $\mathcal{P}$ the linear constraints of the above program.
        The obtained submodular welfare is then precisely 
        $$ALG(SW) = \mathbb{E}\left[\sum_i f_i(\{e\mid (i,t,e)\in S_i \textrm{ for some }t\}) \right] = \mathbb{E}\left[\sum_i h_i(S_i) \right].$$

        For the inefficient solution, we compute an optimal solution $\mathbf{y}$ to the program above and run $ALG$ guided by it.
        But then, by \Cref{lem:rounding-quality}, the correlation gap of monotone submodular functions (\Cref{lem:correlation-submod}) and the choice of $\mathbf{y}$ together with \Cref{obs:OPT_off}, we have
        \begin{align*}
            ALG(SW) & \geq \sum_i H_i\left(\mathbf {y}_{\mid \{i\}\times [m]\times\mathcal{U}}\right) \geq (1-\nicefrac{1}{e}) \sum_i h_i^+\left(\mathbf {y}_{\mid \{i\}\times [m]\times\mathcal{U}}\right) \geq (1-\nicefrac{1}{e}) OPT(SW). 
        \end{align*}

        To obtain a polynomial-time algorithm, it suffices to efficiently compute a vector $\mathbf{y}\in \mathcal{P}$ (for $\mathcal{P}$ the constraints defining the above program) where $\mathbf{y}\in \arg\max_{\mathbf{z}\in \mathcal{P}} \sum_i h_i^+(\mathbf{z}_{\{i\}\times [m]\times \mathcal{U}})$.
        However, this is NP-hard \cite{vondrak2007submodularity}. 
        To overcome this, we rely on a  recent algorithm by Buchbinder, Naor and Wajc \cite{buchbinder2025chasing} to obtain in $\mathrm{poly}(n,m,u)$ time, a point $\mathbf{y}\in \mathcal{P}$ satisfying instead 
        \begin{align}
        \mathbb{E}\left[\sum_i H_i(\mathbf{y}_{\mid \{i\}\times [m]\times \mathcal{U}}) \right] \geq (1-\nicefrac{1}{e}-o(1)) \max_{\mathbf{z}\in \mathcal{P}} \sum_i h_i^+(\mathbf{z}_{\mid \{i\}\times [m]\times \mathcal{U}}).\label{eqn:approximate-noniid-solution}
        \end{align}
        Such a point can also be computed using the continuous greedy algorithm, as shown by \cite{arxiv2009chekuri}. See \Cref{lem:polytime-noniid} for details. Given this algorithm's (efficiently-computable) output $\mathbf{y}$ as in \eqref{eqn:approximate-noniid-solution}, we have, by \Cref{lem:rounding-quality}, the choice of $\mathbf{y}$, together with \Cref{obs:OPT_off}, that
        \begin{align*}
            ALG(SW) & \geq \mathbb{E}\left[\sum_i H_i\left(\mathbf {y}_{\mid \{i\}\times [m]\times\mathcal{U}}\right)\right] \\
            & \geq (1-\nicefrac{1}{e}-o(1)) \max_{z\in \mathcal{P}} \sum_i h_i^+\left(\mathbf {z}_{\mid \{i\}\times [m]\times\mathcal{U}}\right) \\
            & \geq (1-\nicefrac{1}{e}-o(1)) OPT(SW). \qedhere 
        \end{align*}

At each round, since uniformly random buyers are deactivated, this preserves the average in expectation of current $\|\mathbf{x}^{(i)}\|_1$ value for active buyers.\footnote{This is precisely where we use that any online algorithm $ALG$ can only query $f_i(S)$ for $S$ a set of previously arrived items: $ALG$ does not know the deactivated buyers in round $r$, i.e.,  $D^{(r)}$, and so conditional on the history immediately before the round-$r$ deactivation, $D^{(r)}$ is uniform among the currently active buyers, independently of the fractional assignment during the rounds up to round $r$ (by the principle of deferred decision \cite{mitzenmacher2017probability}).}
    During round $r$ with arrival times $R$, the number of active buyers is $n-(r-1)(n/c)$, and $\|\mathbf{x}\|_1$ increases by at most $\sum_{t\in R} \sum_i y_{i,t} \leq \sum_{t\in R} 1 = |R| = nk/c$. 
    Therefore, the average $\|\mathbf{x}\|_1$ over active buyer $i\in \bigcup_{j\geq r} \mathcal{D}^{(j)}$ increases by at most $(nk/c)/(n-(r-1)(n/c))$. The lemma then follows by the following standard calculations:
    \begin{align*}
         \mathbb{E}[\|\mathbf{x}^{(i)}\|_1] & \leq \sum_{j\leq r}\frac{nk/c}{n-(j-1)(n/c)} \\
        & = \sum_{j\leq r} \frac{k}{c-(j-1)} \\
        & = k\cdot \sum_{j=c-r+1}^c \frac{1}{j} \\
        & = k\cdot \left(H_c - H_{c-r}\right).\qedhere 
    \end{align*}

\label{fact:1-(1-1/k)^(k*harmonicdiff)}
Let $c$ and $r\leq c$ be constant integers and $k\geq 2$. Then 
    $$1-\left(1-\frac{1}{k}\right)^{k\cdot \left(H_c - H_{c-r}\right)} \leq \frac{r}{c} + O\left(\frac{1}{k}\right).$$

\label{lem:g_extensions}
	For the extensions $g^+_\sigma, g^1,$ and $g^2$, the following hold:
	\begin{enumerate}
		\item $g^1(\mathds{1}_S) = g^2(\mathds{1}_S) = g(S)$ for every $S \subseteq \mathcal{E}$, and $g^+_\sigma(\mathds{1}_S) = g(S)$ for every feasible allocation $S \in \mathcal{M}_\sigma$.
		\item $g^+_\sigma(\mathbf{x}) \leq \min \{g^1(\mathbf{x}), g^2(\mathbf{x})\}$ for every $\mathbf{x} \in \mathrm{conv}(\mathcal{M}_\sigma)$.
	\end{enumerate}
